forge_api=r'''
async function forgeApi(action,payload={},options={}){
  const controller=new AbortController();const t=setTimeout(()=>controller.abort(),options.timeout||30000);
  try{const res=await fetch(FORGE_URL,{method:'POST',headers:{'Content-Type':'application/json','apikey':API_KEY},body:JSON.stringify({action,...payload,...(S.token?{token:S.token}:{})}),signal:controller.signal});const data=await res.json().catch(()=>({error:'Invalid Forge response'}));if(!res.ok)throw Object.assign(new Error(data.error||`Forge request failed (${res.status})`),{status:res.status,data});return data}finally{clearTimeout(t)}
}
'''
