forge_block=r'''
function forgeTime(v){try{return new Date(v).toLocaleString([],{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}catch{return''}}
function forgeWorkoutCard(s){if(!s)return'';return `<section class="forge-workout-card"><span class="eyebrow">WORKOUT COMPLETE</span><h3>${esc(s.workoutName||'Workout')}</h3><div class="forge-workout-stats"><span>${Math.round((s.durationSeconds||0)/60)} min</span><span>${s.setCount||0} sets</span><span>${(s.exercises||[]).length} exercises</span></div>${(s.exercises||[]).slice(0,6).map(e=>`<div class="forge-exercise-line"><span>${esc(e.name)}</span><strong>${e.sets} sets</strong></div>`).join('')}</section>`}
function forgeMedia(media=[]){if(!media.length)return'';return `<div class="forge-media ${media.length===2?'compare':''}">${media.map(m=>`<figure>${m.comparison_label&&m.comparison_label!=='single'?`<figcaption>${esc(m.comparison_label)}</figcaption>`:''}<img src="${esc(m.url||'')}" alt="Progress photo" loading="lazy" decoding="async"></figure>`).join('')}</div>`}
function forgeComment(c){return `<div class="forge-comment"><div><strong>${esc(c.author?.display_name||'Athlete')}</strong> <span class="muted tiny">@${esc(c.author?.username||'athlete')} · ${forgeTime(c.created_at)}</span></div><p>${esc(c.body)}</p>${c.user_id===S.user.id?`<button class="linkbtn" data-forge-delete-comment="${c.id}">Delete</button>`:''}</div>`}
function forgePostCard(p){const mine=p.is_mine,react=p.my_reaction;return `<article class="forge-post card"><header class="forge-author"><div class="profile-avatar small">${initials(p.author?.display_name)}</div><div><strong>${esc(p.author?.display_name||'BodySmith athlete')}</strong><div class="muted tiny">@${esc(p.author?.username||'athlete')} · ${forgeTime(p.created_at)}</div></div>${mine?'<span class="pill">Your post</span>':''}</header>${p.caption?`<p class="forge-caption">${esc(p.caption)}</p>`:''}${forgeWorkoutCard(p.workout_summary)}${forgeMedia(p.media)}<div class="forge-reactions"><button class="reaction ${react==='like'?'active':''}" data-forge-react="${p.id}|like" aria-pressed="${react==='like'}">♡ ${p.reactions?.like||0}</button><button class="reaction ${react==='strong'?'active':''}" data-forge-react="${p.id}|strong" aria-pressed="${react==='strong'}">💪 ${p.reactions?.strong||0}</button><button class="reaction ${react==='fire'?'active':''}" data-forge-react="${p.id}|fire" aria-pressed="${react==='fire'}">🔥 ${p.reactions?.fire||0}</button></div><div class="forge-comments">${(p.comments||[]).map(forgeComment).join('')}<form class="forge-comment-form" data-forge-comment="${p.id}"><input name="comment" maxlength="800" placeholder="Encourage them…" aria-label="Comment"><button class="secondary">Post</button></form></div>${mine?`<button class="linkbtn danger-text" data-forge-delete="${p.id}">Delete post</button>`:`<details class="forge-safety"><summary>Post options</summary><label class="field">Report reason<select data-forge-report-reason="${p.id}"><option value="spam">Spam</option><option value="harassment">Harassment</option><option value="sexual_content">Sexual content</option><option value="hate">Hate</option><option value="dangerous_content">Dangerous content</option><option value="impersonation">Impersonation</option><option value="other">Other</option></select></label><div class="row-actions"><button class="secondary" data-forge-report="${p.id}">Report</button><button class="dangerbtn" data-forge-block="${p.user_id}">Block user</button></div></details>`}</article>`}
function forgeComposerView(){const type=S.forgeComposer?.type||'text',selected=S.forgeComposer?.sessionId||S.history.find(h=>h.status==='completed')?.id||'';const workouts=S.history.filter(h=>h.status==='completed').slice(0,30);return `<form id="forgeComposer" class="panel forge-composer" data-type="${esc(type)}"><div class="mini-row"><div><span class="eyebrow">NEW POST</span><h2>Share with The Forge</h2></div><button type="button" class="secondary" data-forge-cancel>Cancel</button></div><label class="field">Post type<select id="forgePostType"><option value="text" ${type==='text'?'selected':''}>Text update</option><option value="progress" ${type==='progress'?'selected':''}>Progress photos</option><option value="workout" ${type==='workout'?'selected':''}>Completed workout</option></select></label><label class="field forge-workout-field">Workout<select id="forgeWorkout">${workouts.map(h=>{const d=h.day_snapshot||h.day||{};return `<option value="${h.id}" ${h.id===selected?'selected':''}>${esc(d.name||'Workout')} · ${new Date(h.started_at).toLocaleDateString()}</option>`}).join('')}</select></label><label class="field">Caption<textarea id="forgeCaption" maxlength="1500" placeholder="What did you accomplish? What are you working toward?"></textarea></label><label class="field forge-progress-field">Progress photos<input id="forgePhotos" type="file" accept="image/jpeg,image/png,image/webp" multiple><span class="field-help">Up to 4 photos. Two photos are labeled Before and After. Photos are re-encoded before upload to remove embedded location/EXIF metadata.</span></label><div class="forge-privacy-note">Nothing is posted automatically. You will publish this post explicitly.</div><button class="primary huge" type="submit">Post to The Forge</button></form>`}
function forgeView(){return shell(`<div class="forge-hero"><div><span class="eyebrow">BODYSMITH COMMUNITY</span><h1>The Forge</h1><p>Show the work. Celebrate progress. Keep each other moving.</p></div><button class="primary" data-forge-new>+ Post</button></div>${S.forgeComposer?forgeComposerView():''}${S.forgeLoading&&!S.forgePosts.length?'<div class="empty">Loading The Forge…</div>':S.forgePosts.length?`<div class="forge-feed">${S.forgePosts.map(forgePostCard).join('')}</div>`:'<section class="panel empty">The Forge is quiet. Be the first to share a workout or progress update.</section>'}${S.forgeCursor?'<button class="secondary huge" data-forge-more>Load more</button>':''}<p class="muted tiny forge-rules">Keep it supportive. Progress photos are optional. Report or block content that does not belong here.</p>`,'forge')}
async function loadForge(reset=false){if(S.forgeLoading||!S.online)return;S.forgeLoading=true;if(reset){S.forgePosts=[];S.forgeCursor=null}if(S.screen==='forge')render();try{const d=await forgeApi('feed',{limit:20,before:reset?null:S.forgeCursor});S.forgePosts=reset?(d.posts||[]):[...S.forgePosts,...(d.posts||[])];S.forgeCursor=d.nextCursor||null}catch(e){toast(e.message,true)}finally{S.forgeLoading=false;if(S.screen==='forge')render()}}
async function loadForgeMine(){if(!S.online)return;try{const d=await forgeApi('profile_posts',{userId:S.user.id});S.forgeMine=d.posts||[];if(S.screen==='profile')render()}catch{}}
function forgeProfileSection(){return `<section class="panel"><div class="mini-row"><div><h3 style="margin:0">The Forge</h3><p class="muted tiny" style="margin:4px 0 0">Your public community posts</p></div><button class="secondary" data-open-forge>Open Forge</button></div>${S.forgeMine.length?S.forgeMine.slice(0,3).map(p=>`<div class="mini-row"><div><strong>${p.post_type==='workout'?esc(p.workout_summary?.workoutName||'Workout'):p.post_type==='progress'?'Progress update':'Community post'}</strong><div class="muted tiny">${forgeTime(p.created_at)} · ${esc((p.caption||'').slice(0,90))}</div></div></div>`).join(''):'<p class="muted">No public Forge posts yet.</p>'}</section>`}
function fileDataUrl(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Could not read image.'));r.readAsDataURL(blob)})}
function loadForgeImage(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{URL.revokeObjectURL(url);resolve(img)};img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Could not open that image.'))};img.src=url})}
async function prepareForgeImage(file){if(!/^image\/(jpeg|png|webp)$/.test(file.type))throw Error('Use JPEG, PNG, or WebP photos.');const img=await loadForgeImage(file),scale=Math.min(1,1600/Math.max(img.naturalWidth,img.naturalHeight)),w=Math.max(1,Math.round(img.naturalWidth*scale)),h=Math.max(1,Math.round(img.naturalHeight*scale)),canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;canvas.getContext('2d').drawImage(img,0,0,w,h);const blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.84));if(!blob||blob.size>5*1024*1024)throw Error('That photo is too large after processing.');return{data:await fileDataUrl(blob),mime:'image/jpeg',width:w,height:h}}
async function submitForge(form){if(!S.online)throw Error('Connect to the internet to post to The Forge.');const type=document.getElementById('forgePostType').value,caption=document.getElementById('forgeCaption').value.trim(),files=[...(document.getElementById('forgePhotos')?.files||[])];if(type==='progress'&&!files.length)throw Error('Choose at least one progress photo.');if(files.length>4)throw Error('Choose up to four photos.');const visibility=type==='progress'?'private':'public',payload={postType:type,caption,visibility};if(type==='workout')payload.workoutSessionId=document.getElementById('forgeWorkout').value;let created;try{created=(await forgeApi('create_post',payload)).post;if(type==='progress'){for(let i=0;i<files.length;i++){const image=await prepareForgeImage(files[i]),label=files.length===2?(i===0?'before':'after'):'single';await forgeApi('upload_media',{postId:created.id,...image,comparisonLabel:label},{timeout:45000})}await forgeApi('update_post',{postId:created.id,visibility:'public',caption})}S.forgeComposer=null;await loadForge(true);toast('Posted to The Forge')}catch(e){if(created?.id)try{await forgeApi('delete_post',{postId:created.id})}catch{}throw e}}
function bindForge(){
 const one=(sel,fn)=>document.querySelectorAll(sel).forEach(el=>el.onclick=async ev=>{ev.preventDefault();try{await fn(el)}catch(e){toast(e.message||'Forge action failed.',true)}});
 one('[data-forge-new]',()=>{S.forgeComposer={type:'text'};render()});one('[data-forge-cancel]',()=>{S.forgeComposer=null;render()});one('[data-forge-more]',()=>loadForge(false));one('[data-open-forge]',async()=>{S.screen='forge';render();await loadForge(true)});
 one('[data-forge-workout]',async el=>{S.screen='forge';S.forgeComposer={type:'workout',sessionId:el.dataset.forgeWorkout};render();await loadForge(true)});
 one('[data-forge-react]',async el=>{const [postId,reaction]=el.dataset.forgeReact.split('|'),p=S.forgePosts.find(x=>x.id===postId),next=p?.my_reaction===reaction?'':reaction;await forgeApi('react',{postId,reaction:next});await loadForge(true)});
 one('[data-forge-delete]',async el=>{if(!confirm('Delete this Forge post?'))return;await forgeApi('delete_post',{postId:el.dataset.forgeDelete});await loadForge(true)});
 one('[data-forge-delete-comment]',async el=>{await forgeApi('delete_comment',{commentId:el.dataset.forgeDeleteComment});await loadForge(true)});
 one('[data-forge-report]',async el=>{const postId=el.dataset.forgeReport,reason=document.querySelector(`[data-forge-report-reason="${postId}"]`).value;await forgeApi('report',{targetType:'post',targetId:postId,reason});toast('Report received. Thank you.');});
 one('[data-forge-block]',async el=>{if(!confirm('Block this user? You will no longer see each other in The Forge.'))return;await forgeApi('block',{userId:el.dataset.forgeBlock});await loadForge(true);toast('User blocked')});
 document.querySelectorAll('.forge-comment-form').forEach(form=>form.onsubmit=async ev=>{ev.preventDefault();const input=form.querySelector('input'),body=input.value.trim();if(!body)return;try{await forgeApi('comment',{postId:form.dataset.forgeComment,body});input.value='';await loadForge(true)}catch(e){toast(e.message,true)}});
 const composer=document.getElementById('forgeComposer');if(composer){const type=document.getElementById('forgePostType');type.onchange=()=>composer.dataset.type=type.value;composer.onsubmit=async ev=>{ev.preventDefault();const button=composer.querySelector('button[type=submit]');button.disabled=true;button.textContent='Posting…';try{await submitForge(composer)}catch(e){toast(e.message,true);button.disabled=false;button.textContent='Post to The Forge'}}}
}
'''
