Path('tests/forge-backend-smoke.mjs').write_text(r'''import assert from 'node:assert/strict';import{randomBytes}from'node:crypto';const KEY='sb_publishable_ibEVVafS4THz-16p4euMfg_qjG2WeU2',MAIN='https://uuzctytbguqjumwpczfh.supabase.co/functions/v1/bodysmith-api',FORGE='https://uuzctytbguqjumwpczfh.supabase.co/functions/v1/bodysmith-forge';async function call(url,action,payload={},token='',status=200){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json',apikey:KEY},body:JSON.stringify({action,...payload,token})});const d=await r.json();assert.equal(r.status,status,`${action}: ${JSON.stringify(d)}`);return d}const cleanup=[];try{assert.equal((await call(FORGE,'health')).ok,true);const password=randomBytes(24).toString('base64url'),mk=async name=>{const a=await call(MAIN,'register',{username:'bodysmith_qa_'+randomBytes(6).toString('hex'),password,displayName:name,qaMode:true},'',201);cleanup.push(a.token);return a};const a=await mk('Forge QA One'),b=await mk('Forge QA Two');let boot=await call(MAIN,'bootstrap',{},a.token),day=boot.plan.plan_days[0],start=await call(MAIN,'start_session',{planDayId:day.id},a.token,201);await call(MAIN,'complete_session',{sessionId:start.session.id},a.token);const workout=(await call(FORGE,'create_post',{postType:'workout',caption:'QA workout',workoutSessionId:start.session.id,visibility:'public'},a.token,201)).post;let feed=await call(FORGE,'feed',{},b.token);assert.ok(feed.posts.some(p=>p.id===workout.id&&p.workout_summary&&!JSON.stringify(p.workout_summary).includes('pain')));await call(FORGE,'react',{postId:workout.id,reaction:'fire'},b.token);await call(FORGE,'comment',{postId:workout.id,body:'Strong work'},b.token,201);feed=await call(FORGE,'feed',{},a.token);const seen=feed.posts.find(p=>p.id===workout.id);assert.equal(seen.reactions.fire,1);assert.ok(seen.comments.some(c=>c.body==='Strong work'));const privatePost=(await call(FORGE,'create_post',{postType:'progress',caption:'Private upload test',visibility:'private'},a.token,201)).post;const jpeg='data:image/jpeg;base64,';await call(FORGE,'upload_media',{postId:privatePost.id,data:jpeg,mime:'image/jpeg',width:1,height:1,comparisonLabel:'single'},a.token,201);let profile=await call(FORGE,'profile_posts',{userId:a.user.id},b.token);assert.ok(!profile.posts.some(p=>p.id===privatePost.id));await call(FORGE,'update_post',{postId:privatePost.id,visibility:'public'},a.token);profile=await call(FORGE,'profile_posts',{userId:a.user.id},b.token);const progress=profile.posts.find(p=>p.id===privatePost.id);assert.ok(progress?.media?.[0]?.url?.startsWith('https://'));await call(FORGE,'block',{userId:a.user.id},b.token);feed=await call(FORGE,'feed',{},b.token);assert.ok(!feed.posts.some(p=>p.user_id===a.user.id));await call(FORGE,'unblock',{userId:a.user.id},b.token);await call(FORGE,'report',{targetType:'post',targetId:workout.id,reason:'other',details:'QA report'},b.token);await call(FORGE,'delete_post',{postId:privatePost.id},a.token);profile=await call(FORGE,'profile_posts',{userId:a.user.id},b.token);assert.ok(!profile.posts.some(p=>p.id===privatePost.id));console.log('PASS Forge workout posts, private progress media, signed delivery, reactions, comments, block/report and deletion');}finally{for(const token of cleanup)try{await call(MAIN,'cleanup_qa',{},token)}catch{}}''')

